+
+<h3>My Shipments</h3>
+
+@if (myShipments is null)
+{
+    <p><em>Loading your shipments...</em></p>
+}
+else if (myShipments.Length == 0)
+{
+    <p class="text-muted">No shipments associated with your account yet.</p>
+}
+else
