@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Dispatch Center</PageTitle>

<h1>📦 Dispatch Center</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ToggleNewShipmentForm">
        @(showNewForm ? "Cancel" : "➕ New Shipment")
    </button>
</div>

@if (showNewForm)
{
    <div class="card mb-4 p-3">
        <h4>Create New Shipment</h4>
        <div class="row g-2">
            <div class="col-md-4">
                <input class="form-control" placeholder="Origin" @bind="newOrigin" />
            </div>
            <div class="col-md-4">
                <input class="form-control" placeholder="Destination" @bind="newDestination" />
            </div>
            <div class="col-md-4">
                <input class="form-control" placeholder="Customer Email" @bind="newCustomerEmail" />
            </div>
            <div class="col-md-6">
                <input class="form-control" placeholder="Description" @bind="newDescription" />
            </div>
            <div class="col-md-4">
                <input class="form-control" type="date" @bind="newEstimatedDelivery" />
            </div>
            <div class="col-md-2">
                <button class="btn btn-success w-100" @onclick="CreateShipment">Create</button>
            </div>
        </div>
    </div>
}

@if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Length == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input class="form-control" placeholder="Filter by destination or tracking #..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><strong>@shipment.TrackingNumber</strong></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">
                            @shipment.Status
                        </span>
                    </td>
                    <td>@shipment.CustomerEmail</td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString())">
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Cancelled">Cancelled</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Length shipments</p>
}

@code {
    private ShipmentDto[]? shipments;
    private string filterText = string.Empty;
    private string? errorMessage;
    private bool showNewForm;

    private string newOrigin = string.Empty;
    private string newDestination = string.Empty;
    private string newCustomerEmail = string.Empty;
    private string newDescription = string.Empty;
    private DateTime? newEstimatedDelivery = DateTime.Today.AddDays(7);

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<ShipmentDto[]>("/api/shipments");
            errorMessage = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task UpdateStatus(int id, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus)) return;

        try
        {
            var response = await Http.PutAsJsonAsync($"/api/shipments/{id}/status", new { Status = newStatus });
            if (response.IsSuccessStatusCode)
            {
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to update status.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error: {ex.Message}";
        }
    }

    private void ToggleNewShipmentForm() => showNewForm = !showNewForm;

    private async Task CreateShipment()
    {
        try
        {
            var request = new
            {
                Origin = newOrigin,
                Destination = newDestination,
                EstimatedDelivery = newEstimatedDelivery,
                CustomerEmail = newCustomerEmail,
                Description = newDescription
            };

            var response = await Http.PostAsJsonAsync("/api/shipments", request);
            if (response.IsSuccessStatusCode)
            {
                showNewForm = false;
                newOrigin = newDestination = newCustomerEmail = newDescription = string.Empty;
                newEstimatedDelivery = DateTime.Today.AddDays(7);
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to create shipment.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error: {ex.Message}";
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

